ser.com/michigan-claim-appraisal/homeowner-claim-appraiser/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, Condo & HOA Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/commercial-condo-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hail & Roof Damage Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/hail-roof-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Windstorm & Tornado Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/windstorm-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam & Frozen Pipe Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/ice-dam-frozen-pipe-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Sewer Backup Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/water-sewer-backup-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Loss Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/fire-smoke-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree & Ice Storm Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/fallen-tree-ice-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Contents & Personal Property","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/contents-personal-property-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Estimate Second Opinion","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/insurance-estimate-second-opinion/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Xactimate estimating","Ice dam claims","Sewer backup claims","Hail damage"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://michiganinsuranceappraiser.com/#website","url":"https://michiganinsuranceappraiser.com/","name":"Michigan Insurance Appraiser","publisher":{"@id":"https://michiganinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#webpage","url":"https://michiganinsuranceappraiser.com/insurance-claim-terms/","name":"Insurance Claim Terms Glossary | ACV, RCV & More","description":"Searchable insurance claim terms glossary for Michigan owners: ACV, RCV, holdback, umpire, ice dam, sewer backup, DIFS and more, defined.","inLanguage":"en-US","isPartOf":{"@id":"https://michiganinsuranceappraiser.com/#website"},"about":{"@id":"https://michiganinsuranceappraiser.com/#business"},"publisher":{"@id":"https://michiganinsuranceappraiser.com/#business"},"dateModified":"2026-11-18","primaryImageOfPage":{"@type":"ImageObject","url":"https://michiganinsuranceappraiser.com/assets/img/photos/paperwork.webp","width":1200,"height":798},"breadcrumb":{"@id":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#breadcrumb"},"mainEntity":{"@id":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://michiganinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim glossary","item":"https://michiganinsuranceappraiser.com/insurance-claim-terms/"}],"@id":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#breadcrumb"},{"@type":"DefinedTermSet","name":"Michigan property insurance claim glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value","description":"The value of damaged property at the time of loss, usually replacement cost minus depreciation. Many policies pay this amount first.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Replacement cost value","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deducting depreciation.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value assigned to property because of age, wear and condition. It is the difference between replacement cost and actual cash value.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation the insurer withholds at first but pays once repairs or replacement are completed, under a replacement cost policy.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Holdback","description":"The portion of a claim payment, usually recoverable depreciation, that the insurer keeps back until repairs are done and documented.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of the covered damage. In appraisal, this is the figure the award sets.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either side demand appraisal when they disagree on the amount of loss. Michigan law requires it in property policies.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision, signed by any two of the two appraisers and the umpire, that determines the amount of loss.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Umpire","description":"A neutral person chosen by the two appraisers, or by a court if they can’t agree, who decides items the appraisers can’t settle.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Competent and independent appraiser","description":"An appraiser with the skill to value the loss and no financial interest or bias that would compromise their judgment.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement from the policyholder describing the loss and the amount claimed, often required within a set time after the insurer asks for it.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, property, coverage limits, deductibles and policy period.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Deductible","description":"The amount the policyholder pays toward a covered loss before the insurer’s payment applies.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible set as a percentage of the dwelling limit rather than a flat dollar amount, sometimes used for wind or hail losses.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage for the house itself and attached structures such as an attached garage.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage for detached buildings such as sheds, fences and detached garages.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage for the contents of the home, such as furniture, clothing and electronics.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage D","description":"Loss of use coverage, which pays additional living expenses or fair rental value while the home can’t be lived in.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs to bring repaired property up to current building codes, subject to its own limit.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs match in color, texture and appearance. Policy wording and the facts control.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Line of sight","description":"An approach to matching that looks at whether repaired and unrepaired areas are visible together as one continuous surface.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Overhead and profit","description":"A contractor’s charge for business costs and margin, often 10% plus 10% in estimates, typically included when a general contractor is reasonably needed.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers, adjusters and contractors that prices repairs line by line using regional price lists.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and the repairs needed to restore them, before pricing is applied.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment after the first estimate, usually for damage or costs found once repairs begin.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the roof edge that traps melting snow, which can back up under shingles and leak into the home.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Sewer and drain backup endorsement","description":"An optional add-on that covers water backing up through sewers or drains, which standard homeowner policies usually exclude.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Surface water","description":"Water from rain or snowmelt flowing over the ground. Damage from it is usually excluded as flood, not covered as backup.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Wear and tear","description":"Gradual deterioration from age and use. Policies generally exclude it, and insurers sometimes cite it to deny or reduce roof claims.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps taken after a loss to prevent further damage, such as tarping a roof or drying a wet basement.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Additional living expenses","description":"Increased costs of living elsewhere, such as rent and meals above normal, while a damaged home is repaired.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for the cost of hauling away damaged property and debris, sometimes with its own limit.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Suit limitation","description":"A policy or statutory deadline to sue. In Michigan it is generally one year after the loss, tolled while the claim is pending.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Tolling","description":"Pausing a deadline for a period of time. Michigan’s suit limitation is generally tolled from notice of loss until a formal denial.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Penalty interest","description":"Interest owed on certain late claim payments. Michigan’s MCL 500.2006 provides for 12% per year in certain circumstances.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"DIFS","description":"The Michigan Department of Insurance and Financial Services, the state agency that regulates insurers and takes consumer complaints.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"MBPIA","description":"The Michigan Basic Property Insurance Association, Michigan’s FAIR Plan for owners who can’t get coverage in the voluntary market.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer continues handling a claim while reserving the right to deny coverage later.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Examination under oath","description":"Sworn questioning of the policyholder by the insurer’s representative, which many policies allow the insurer to require.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Square (roofing)","description":"A roofing unit equal to 100 square feet of roof surface.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Pitch","description":"The steepness of a roof, expressed as inches of rise per 12 inches of run. Steeper pitches cost more to work on.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Drip edge","description":"Metal flashing installed along roof edges to direct water away from the fascia and into the gutters.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering waterproof underlayment installed at eaves and valleys to resist ice dam leaks, often required by code in cold climates.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Lake-effect snow","description":"Heavy snow produced when cold air crosses the warmer Great Lakes, common along the west Michigan lakeshore and in the U.P.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Collapse coverage","description":"Limited coverage for sudden collapse of a building or part of one caused by specific listed perils, such as the weight of snow or ice.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Public adjuster","description":"A licensed professional hired by a policyholder to prepare and negotiate a claim, usually for a percentage of the recovery.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"},{"@type":"DefinedTerm","name":"Unfair claims practices","description":"Conduct barred by Michigan’s Uniform Trade Practices Act, such as failing to promptly investigate or pay claims.","inDefinedTermSet":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}],"@id":"https://michiganinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}]}</script>
</head>
